def norm(s):return re.sub(r'\s+',' ',s).strip()
def ev(b,id,term,provision,asof='',size=900,last=False):
 p=ROOT/'evidence'/f'native_batch{b:02}'/(id+'.txt');s=norm(p.read_text());i=s.rfind(term) if last else s.find(term)
 if i<0:raise ValueError((b,id,term))
 rp=p.with_suffix('.receipt.json');r=json.loads(rp.read_text());j=p.with_suffix('.json');doc=json.loads(j.read_text())['data']['docNum'] if j.exists() else r.get('document','')
 return dict(url=r['url'],source_tier='official',document_number=doc,provision=provision,as_of=asof,quote=s[i:i+size],accessed_at=r['accessed_at'])
def xev(url,doc,provision,quote,asof='',tier='official'):
 return dict(url=url,source_tier=tier,document_number=doc,provision=provision,as_of=asof,quote=quote,accessed_at=NOW)
def label(a,**changes):
 z={k:a[k] for q in range(1,5) for k in (f'q{q}',f'q{q}_reason')};z.update(changes);return z
def write(b,specs):
 cases=list(map(json.loads,(ROOT/'input'/f'batch{b:02}.jsonl').read_text().splitlines()));out=[]
 for c,(labs,reason,es,questions) in zip(cases,specs):
  o={k:c[k] for k in ['case_id','run_id','lineage_id','worksheet_sha256','raw_a_sha256','raw_b_sha256','disputed_fields']};o.update(reasoning=reason,evidence=es,open_questions=questions,labeler='ai-adjudicator',label_origin='ai',verification_status='not_verified',human_adjudication_required=True)
  if labs is None:
   o.update(disposition='unresolved',proposed_label=None)
   if b==7 and c['lineage_id'].startswith('provision:5400b11e'):o.update(confirmed_fields={'q4':'co','q4_reason':'superseded_by_other_norm'},verdict_conclusion='khong_dat')
  else:
   labs['verdict']='dat' if all(labs[q]==v for q,v in {'q1':'dung','q2':'co','q3':'co','q4':'khong'}.items()) else 'khong_dat';labs.update(quote=es[0]['quote'],search_log='Đã mở lại API CSDL quốc gia của bản gốc và toàn bộ văn bản tác động nêu trong phiếu; đọc câu dẫn, nội dung sửa đổi, điều hiệu lực/chuyển tiếp. Các nguồn kiểm thêm được ghi ở evidence. Không phải hồ sơ T6.',note=reason,evidence_status='sufficient',evidence=es)
   fields=[k for q in range(1,5) for k in (f'q{q}',f'q{q}_reason')];matches=[s for s in 'ab' if all(labs[k]==c[s][k] for k in fields)];o.update(disposition='prefer_'+matches[0] if matches else 'both_wrong',proposed_label=labs)
  out.append(o)
 p=ROOT/'results'/f'batch{b:02}.jsonl';p.parent.mkdir(exist_ok=True);assert not p.exists(),p;p.write_text(''.join(json.dumps(o,ensure_ascii=False)+'\n' for o in out));print(p,len(out))
 receipts=[json.loads(p.read_text()) for p in (ROOT/'evidence'/f'native_batch{b:02}').glob('*.receipt.json')]
 meta=dict(runtime='native Codex subagent fallback; Claude CLI unavailable due weekly limit (reported by coordinator)',model='unknown; inherited',agent_spec='.claude/agents/legal-adjudicator.md',agent_spec_sha256=hashlib.sha256(pathlib.Path('.claude/agents/legal-adjudicator.md').read_bytes()).hexdigest(),input_sha256=hashlib.sha256((ROOT/'input'/f'batch{b:02}.jsonl').read_bytes()).hexdigest(),guideline_version='4.0',tools_used=['exec_command read-only local inspection, urllib.request/curl official source retrieval; pdftotext/pdftoppm where relevant','web.run search/open/find/screenshot','view_image where relevant'],tool_adaptation='Native runtime has no Claude Read/Write adapters. exec file I/O is used only for packets, authority, own evidence/results/metadata. No model switch or downstream agents.',lawgical='not available; no calls, quota unknown',started_at='2026-11-07T09:29:00+00:00 (approximate; first exact source receipt separately recorded)',completed_at=NOW,access_errors=['Sandbox DNS Errno -3; escalated requests succeeded for API','vbpl.moj.gov.vn attachment DNS Errno -2; vbpl.vn attachment HTTP403','g7.cdnchinhphu.vn Python/curl certificate chain verification failed; no TLS bypass','Some web fetches cache miss / screenshot timeout; official API and old official CDN used as fallback'],sources=receipts,urls=sorted({e['url'] for o in out for e in o['evidence']}),blindness='Adjudicator saw locked A and B as intended; no systems output or datasets/source labels edited',human_adjudication_required=True)
 p=ROOT/'metadata'/f'native_batch{b:02}.json';p.parent.mkdir(exist_ok=True);assert not p.exists();p.write_text(json.dumps(meta,ensure_ascii=False,indent=2))
 return out
